# Search for solutions (a, b, c) to 2^a + 3^b + 1 = 6^c where 1 <= a, b, c <= 5

solutions = []
for a in range(1, 6):
    for b in range(1, 6):
        for c in range(1, 6):
            LHS = 2**a + 3**b + 1
            RHS = 6**c
            if LHS == RHS:
                solutions.append((a, b, c))

print("Solutions found (a, b, c):")
if solutions:
    for sol in solutions:
        print(sol)
else:
    print("No solutions found in the given range.")
